static int removeAllShorterThan(List<String> words, int minLength) {
    int removed = 0;
    for (int i = 0; i < words.size(); i++) {
        if (words.get(i).length() < minLength) {
            words.remove(i);
            removed++;
        }
    }
    return removed;
}

